#!/usr/bin/env python3
"""Replication guide (author 2026-10-15): "the only code sent to be replicated comes as our full chain code." Generates
Biological_Physics/MethylPhys/REPLICATE.md from the code: the chain's entry points (CANON/chain_manifest.py ENTRY), its run command
(the arguments of run_sample.py, read from the source), its own check (release_check_v3.py), the commissioned instruments
(CANON/commissioning.json), and, separately and labeled, every non-chain script a commissioning note still cites (code still to be brought
into the chain). The how-to section may name only chain/ paths; this script refuses to write it otherwise. Usage: replicate.py [--check]"""
import os, re, sys, json, ast
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
CH = "Biological_Physics/MethylPhys/chain"; OUT = "Biological_Physics/MethylPhys/REPLICATE.md"; DOORS = "Biological_Physics/MethylPhys/doors/"
src = open("CANON/chain_manifest.py").read(); ENTRY = ast.literal_eval(re.search(r"ENTRY = (\[[^\]]*\])", src).group(1))
rs = open(f"{CH}/MethylPhys_Interface/run_sample.py", encoding="utf-8").read(); ARGS = re.findall(r'add_argument\("(--[\w-]+)"', rs)
C = json.load(open("CANON/commissioning.json"))["instruments"]
debt = []
for f in sorted(os.listdir(DOORS)):
    if f.startswith("COMMISSIONING_NOTE_") and f.endswith(".md"):
        for x in sorted(set(re.findall(r"[A-Za-z0-9_/.-]+\.(?:py|sh|R)\b", open(DOORS + f, encoding="utf-8").read()))):
            if not x.startswith(("chain/", CH)) and not x.startswith("CANON/"):
                cand = [DOORS + x, DOORS + "data/" + x, "Biological_Physics/MethylPhys/" + x] + [g for g in (DOORS + "data/" + d + "/" + x for d in os.listdir(DOORS + "data") if os.path.isdir(DOORS + "data/" + d)) if os.path.isfile(g)]
                hit = next((c for c in cand if os.path.isfile(c)), None)
                calls = "file not found" if hit is None else ("yes (a driver: feeds data to the chain and records its answer)" if re.search(r"(?m)^\s*(from|import)\s+(conductor_v3|stage_\w+|dev_stages)\b", open(hit, encoding="utf-8", errors="replace").read()) else "no")
                debt.append((f[:-3], x, calls))
HOW = ["## How to replicate (chain code only)", "",
       "1. Clone the repository. The chain is `Biological_Physics/MethylPhys/chain/`; set up its environment from",
       f"   [`chain/requirements.txt`](chain/requirements.txt) (Python 3.11). Full cold start: [`chain/RUN_MANIFEST_and_README.md`](chain/RUN_MANIFEST_and_README.md).",
       "2. Check the chain on its constructed tests: `python3 Biological_Physics/MethylPhys/chain/release_check_v3.py`.",
       "3. Read a specimen: `python3 Biological_Physics/MethylPhys/chain/MethylPhys_Interface/run_sample.py` with",
       "   " + ", ".join(f"`{a}`" for a in ARGS) + ".",
       "4. Every result the chain writes for a logged test carries a chain stamp (chain version, payload hash, inputs); compare yours with ours.",
       "", "Chain entry points: " + ", ".join(f"`chain/{e}.py`" for e in ENTRY) + ".", ""]
for l in HOW:
    for x in re.findall(r"([\w/.-]+\.py)\b", l):
        assert x.startswith(("chain/", CH)), f"replicate.py: the how-to names {x}, which is not chain code - refused"
L = ["# Replicating IAM's cell instruments (generated by CANON/replicate.py; do not edit by hand)", "",
     "**One rule (author, 2026-10-15): the only code we send anyone to replicate is the full chain.** Side scripts in `development/` and in test",
     "folders are exploration history; they are never the replication path. Every test logged from 2026-10-15 on runs through the chain and is",
     "refused by the push gate otherwise (`CANON/chain_gate.py`).", ""] + HOW + \
    ["## Commissioned instruments", "", "| instrument | commissioned | where in the chain |", "|---|---|---|"] + \
    [f"| {i['name']} | {i['date']} | " + ", ".join(sorted({'`' + p['file'].replace(CH + '/', 'chain/') + '`' for p in i['places'] if p['file'].startswith(CH)})) + " |" for i in C] + \
    ["", "## Code still to be brought into the chain (not the replication path)", "",
     "Scripts the commissioning notes cite that are not chain code: they built frozen inputs or computed a note's figures. Until each is moved",
     "into the chain, its output is used only as a frozen chain input, and its own script is history.", "", "| commissioning note | script | calls the chain |", "|---|---|---|"] + \
    [f"| {n} | `{x}` | {c} |" for n, x, c in debt] + [""] + [("#" + x) if x.startswith("# ") else x for x in __import__("not_chain_verified").section()[0]]
text = "\n".join(L) + "\n"
if "--check" in sys.argv:
    ok = os.path.exists(OUT) and open(OUT, encoding="utf-8").read() == text
    print("replicate: " + ("ok" if ok else "REFUSED: REPLICATE.md differs from the code (run python3 CANON/replicate.py)")); sys.exit(0 if ok else 1)
open(OUT, "w", encoding="utf-8").write(text); print(f"replicate: wrote {OUT} ({len(debt)} non-chain scripts listed as still to move)")
